/*
 * AndySU core C ABI. Strings are UTF-8 and NUL-terminated. Every function except
 * andysu_version and andysu_session_free returns a heap-allocated JSON string,
 * {"ok": ...} or {"error": {"code": "...", "message": "..."}}, to be freed with andysu_free.
 */

#ifndef ANDYSU_H
#define ANDYSU_H

/* Generated by cbindgen from core/src/ffi.rs. Do not edit; run scripts/gen-header.sh. */

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

/**
 * Free a string returned by any `andysu_*` function.
 */
void andysu_free(char *p);

/**
 * Library version, static string (do not free).
 */
const char *andysu_version(void);

/**
 * `{"ok": <session handle>}`. `random16` (16 bytes) seeds the install id on first run.
 */
char *andysu_session_new(const char *root, const char *config_json, const uint8_t *random16);

void andysu_session_free(uint64_t h);

/**
 * Verify + parse + select. `etag` may be NULL.
 */
char *andysu_session_check(uint64_t h,
                           const char *manifest_url,
                           const uint8_t *manifest,
                           size_t manifest_len,
                           const uint8_t *sig,
                           size_t sig_len,
                           const char *etag,
                           int64_t now);

/**
 * After HTTP 304: re-verify the cached manifest.
 */
char *andysu_session_check_cached(uint64_t h, int64_t now);

char *andysu_session_plan(uint64_t h);

char *andysu_session_complete(uint64_t h, const char *key);

char *andysu_session_skip_delta(uint64_t h, const char *key);

char *andysu_session_stage(uint64_t h);

/**
 * Cold-start decision; persists before returning. `{"ok":{"slot":..,"slot_dir":..,"in_trial":..,"events":[..]}}`
 */
char *andysu_launch(const char *root,
                    const uint8_t *random16,
                    int64_t now,
                    bool apply_pending,
                    uint32_t max_attempts);

char *andysu_mark_healthy(const char *root);

char *andysu_report_failure(const char *root, const char *reason);

char *andysu_begin_live(const char *root, int64_t now);

/**
 * Recovery: forget installed slots and boot the payload built into the host.
 */
char *andysu_reset(const char *root, const char *reason);

char *andysu_gc(const char *root, bool low_storage);

char *andysu_state(const char *root);

/**
 * Libraries to load (in order), entry library and symbol, dex path for a slot directory.
 */
char *andysu_load_plan(const char *slot_dir, const char *abi);

/**
 * Path a native signal handler should create to report a crash (see `Store::crash_marker_path`).
 */
char *andysu_crash_marker_path(const char *root);

#if defined(ANDYSU_TRANSPORT)
/**
 * One complete check/download/stage cycle over HTTP(S) or file:// (transport feature).
 */
char *andysu_update_http(const char *root,
                         const char *config_json,
                         const char *manifest_url,
                         const uint8_t *random16,
                         int64_t now);
#endif

#endif  /* ANDYSU_H */
